import re

def parse_duration(text):
    if not isinstance(text, str):
        return None

    # A plain string of digits means seconds
    if text.isdigit():
        return int(text)

    # Unit string: optional hours, then optional minutes, then optional seconds
    match = re.fullmatch(r'(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?', text)
    if match:
        h, m, s = match.groups()
        if h is None and m is None and s is None:
            return None  # matched empty string
        total = 0
        if h is not None:
            total += int(h) * 3600
        if m is not None:
            total += int(m) * 60
        if s is not None:
            total += int(s)
        return total

    return None
